        let t = '““””<b><span style="color:#7C6CFF;font-size:17px">▌ ' + title + '</span></b>';
        if (sub) t += '  <small><font color=#8A8A96>' + sub + '</font></small>';
        return {title:t,url:'hiker://empty',col_type:'text_1',extra:{lineVisible:false}};
    },
    softTitle: function(title, sub) {
        title=this.maskText(title); sub=this.maskText(sub);
        let t='““””<b><span style="font-size:16px">'+title+'</span></b>';
        if(sub)t+='  <small><font color=#8A8A96>'+sub+'</font></small>';
        return {title:t,url:'hiker://empty',col_type:'text_1',extra:{lineVisible:false}};
    },
    statChip: function(text) {
        text=this.maskText(text);
        return {title:'““””<small><font color=#777785>'+text+'</font></small>',url:'hiker://empty',col_type:'text_3',extra:{lineVisible:false}};
    },
    compactNum: function(n) {
        n = parseInt(n || 0);
        if (!(n > 0)) return '0';
        if (n >= 100000000) return (n / 100000000).toFixed(n >= 1000000000 ? 0 : 1).replace(/\.0$/,'') + '亿';
        if (n >= 10000) return (n / 10000).toFixed(n >= 100000 ? 0 : 1).replace(/\.0$/,'') + '万';
        return String(n);
    },
    shortTitle: function(v,max) {
        let s=this.cleanText(v||'');
        max=parseInt(max||18);
        return s.length>max?s.slice(0,max)+'…':s;
    },
    sectionLink: function(title, sub, url) {
        title=this.maskText(title); sub=this.maskText(sub);
        let t = '““””<b><span style="color:#7C6CFF;font-size:17px">▌ ' + title + '</span></b>';
        if (sub) t += '  <small><font color=#8A8A96>' + sub + '</font></small>';
        return {title:t,desc:url?'更多  ›':'',url:url||'hiker://empty',col_type:'text_1',extra:{lineVisible:false}};
    },
    heroCard: function(item, type) {
        item = item || {};
        let isDrama = type == 'drama' || item.episodeCount != null || Array.isArray(item.episodes);
        let id = item.id != null ? item.id : (item.videoId != null ? item.videoId : item.shortDramaId);
        let title = this.cleanText(item.title != null ? item.title : item.name) || '未命名';
        let meta = [];
        if (isDrama) {
            if (item.episodeCount != null) meta.push(item.episodeCount + '集');
            if (item.rating != null) meta.push('★ ' + item.rating);
            if (item.heatCount != null) meta.push('🔥' + this.compactNum(item.heatCount));
        } else {
            let du = this.fmtDuration(item.durationSec);
            if (du) meta.push(du);
            if (item.viewCount != null) meta.push('👀' + this.compactNum(item.viewCount));
            if (item.categoryName) meta.push(this.cleanText(item.categoryName));
        }
        return {
            title:title,
            desc:meta.join(' · '),
            img:this.image(item.coverUrl || item.cover || item.image || item.picUrl),
            url:$('hiker://empty?#immersiveTheme#').rule(() => { $.require('mdai').detail(); }),
            col_type:'movie_1',
            extra:{mdai_id:String(id == null ? '' : id),mdai_type:isDrama?'drama':'video',mdai_title:title,pageTitle:title,lineVisible:false}
        };
    },
    localCard: function(x, col) {
        x=x||{};
        return {
            title:x.title||'未命名',
            desc:x.desc||'',
            img:x.cover||'',
            url:$('hiker://empty?#immersiveTheme#').rule(() => { $.require('mdai').detail(); }),
            col_type:col||getItem('mdai_col_type','movie_3'),
            extra:{mdai_id:String(x.id||''),mdai_type:x.type||'video',mdai_title:x.title||'',pageTitle:x.title||''}
        };
    },
    modeButton: function(d, title, id) {
        title=this.maskText(title);
        let now = getMyVar('mdai_mode', 'drama');
        let active = now == id;
        d.push({
            title: active ? '““””<b><font color=#FFFFFF>'+title+'</font></b>' : '‘‘’’<font color=#777785>'+title+'</font>',
            url: $('#noLoading#').lazyRule((id) => {
                putMyVar('mdai_mode', id);
                refreshPage(false);
                return 'hiker://empty';
            }, id),
            col_type: 'scroll_button',
            extra: {backgroundColor: active ? '#806C63FF' : '#0A777785',lineVisible:false}
        });
    },
    videoCard: function(item, type, col) {
        item = item || {};
        let isDrama = type == 'drama' || item.episodeCount != null || Array.isArray(item.episodes);
        let id = item.id != null ? item.id : (item.videoId != null ? item.videoId : item.shortDramaId);
        // 首页标题始终以接口真实 title 为第一优先级，避免分类名/描述覆盖片名。
        let rawTitle = item.title != null ? item.title : (item.name != null ? item.name : '');
        let title = this.cleanText(rawTitle) || '未命名';
        let meta=[];
        if (isDrama) {
            let ep = item.episodeCount != null ? item.episodeCount : ((item.episodes || []).length || '');
            if (ep !== '') meta.push(ep + '集');
            if (item.heatCount != null) meta.push('🔥' + this.compactNum(item.heatCount));
        } else {
            let du = this.fmtDuration(item.durationSec);
            if (du) meta.push(du);
            if (item.viewCount != null) meta.push('👀' + this.compactNum(item.viewCount));
        }
        let sub=[];
        if (!isDrama && item.categoryName) sub.push(this.cleanText(item.categoryName));
        if (item.publishedAt) sub.push(this.fmtDate(item.publishedAt).slice(5,10));
        let desc=meta.join(' · ')+(sub.length ? (meta.length?'\n':'')+sub.join(' · ') : '');
        return {
            // movie 卡片标题不要再包 <b> 富文本，部分海阔版本会造成截断/异常显示。
            title:title,
            desc:desc,
            img:this.image(item.coverUrl || item.cover || item.image || item.picUrl),
            url:$('hiker://empty?#immersiveTheme#').rule(() => { $.require('mdai').detail(); }),
            col_type:col || (isDrama ? 'movie_3' : 'movie_2'),
            extra:{
                mdai_id:String(id == null ? '' : id),
                mdai_type:isDrama ? 'drama' : 'video',
                mdai_title:title,pageTitle:title,lineVisible:false
            }
        };
    },

    getCategories: function(type) {
        type = type || 'video';
        let key='mdai_categories_cache_'+type, tk=key+'_time';
        let cached=getItem(key,'');
        let ts=parseInt(getItem(tk,'0'))||0;
        if(cached && (new Date().getTime()-ts)<21600000){
            try { let a=JSON.parse(cached); if(Array.isArray(a)&&a.length) return a.map(c=>Object.assign({},c,{name:this.maskText(c.name||'')})); } catch(ignore){}
        }
        try {
            let x=this.payload(this.request('/api/v1/categories?type='+encodeURIComponent(type)));
            let a=Array.isArray(x)?x:this.items(x);
            a=(a||[]).filter(c=>c && c.enabled!==false).sort((a,b)=>(parseInt(a.sortOrder||0)-parseInt(b.sortOrder||0))||(parseInt(a.id||0)-parseInt(b.id||0)));
            if(a.length){ setItem(key,JSON.stringify(a)); setItem(tk,String(new Date().getTime())); return a.map(c=>Object.assign({},c,{name:this.maskText(c.name||'')})); }
        } catch(ignore){}
        let fb=type=='post' ? this.fallbackPostCategories.slice() : this.fallbackCategories.slice();
        return fb.map(c=>Object.assign({},c,{name:this.maskText(c.name||'')}));

    },
    menuName: function(id) {
        let m={1:'原创精选',2:'国产视频',3:'中文AV',4:'黑料吃瓜'};
        return m[parseInt(id)]||('频道'+id);
    },
    postCard: function(item, col) {
        item=item||{};
        let id=item.id!=null?item.id:item.postId;
        let title=this.cleanText(item.title||'未命名帖子');
        let excerpt=this.cleanText(item.content||item.description||'').replace(/\n+/g,' ');
        if(excerpt.length>52)excerpt=excerpt.slice(0,52)+'…';
        let meta=[];
        if(item.categoryName)meta.push(this.cleanText(item.categoryName));
        if(item.viewCount!=null)meta.push('👀'+this.compactNum(item.viewCount));
        if(item.publishedAt)meta.push(this.fmtDate(item.publishedAt).slice(5,10));
        let desc=(excerpt?excerpt+'\n':'')+meta.join(' · ');
        let imgs=Array.isArray(item.images)?item.images:[];
        let cover=item.coverUrl||item.cover||(imgs.length?imgs[0]:'');
        return {title:title,desc:desc,img:this.image(cover),url:$('hiker://empty?#immersiveTheme#').rule(()=>{$.require('mdai').detail();}),col_type:col||'movie_2',extra:{mdai_id:String(id),mdai_type:'post',mdai_title:title,pageTitle:title,lineVisible:false}};
    },
    commentsUrl: function(target,id,title) {
        return $('hiker://empty?page=fypage&ct='+encodeURIComponent(target)+'&cid='+encodeURIComponent(id)+'&ctitle='+encodeURIComponent(title||'评论')).rule(()=>{$.require('mdai').comments();});
