        d.push(chip('近1月',!!tr,$('#noLoading#').lazyRule(()=>{let n=getMyVar('mdai_filter_time','')?'':'1m';putMyVar('mdai_filter_time',n);refreshPage(false);return 'hiker://empty';})));
        d.push(chip('20分钟+',!!md,$('#noLoading#').lazyRule(()=>{let n=getMyVar('mdai_filter_duration','')?'':'20';putMyVar('mdai_filter_duration',n);refreshPage(false);return 'hiker://empty';})));
        d.push(chip('点赞优先',!!sb,$('#noLoading#').lazyRule(()=>{let n=getMyVar('mdai_filter_sort','')?'':'likes';putMyVar('mdai_filter_sort',n);refreshPage(false);return 'hiker://empty';})));
        if(tr||md||sb)d.push({title:'重置',url:$('#noLoading#').lazyRule(()=>{clearMyVar('mdai_filter_time');clearMyVar('mdai_filter_duration');clearMyVar('mdai_filter_sort');refreshPage(false);return 'hiker://empty';}),col_type:'scroll_button',extra:{lineVisible:false}});
