    buildVideoPath: function(cat, pg, size, allowFilter) {
        let p='/api/v1/videos?page='+pg+'&size='+size;
        if(cat)p+='&categoryId='+encodeURIComponent(cat);
        if(allowFilter){
            let tr=getMyVar('mdai_filter_time',''), md=getMyVar('mdai_filter_duration',''), sb=getMyVar('mdai_filter_sort','');
            if(tr)p+='&timeRange='+encodeURIComponent(tr);
            if(md)p+='&minDuration='+encodeURIComponent(md);
            if(sb)p+='&sortBy='+encodeURIComponent(sb);
        }
        return p;
    },
    channelHome: function(d, menuId, pg) {
        let cats=this.getCategories('video').filter(c=>parseInt(c.menuId)==parseInt(menuId));
        let key='mdai_menu_cat_'+menuId;
        let cat=getMyVar(key,'');
        if(pg==1){
            d.push(this.sectionTitle(this.menuName(menuId),cat?'分类浏览':'精选内容'));
            let makeChip=(name,id,active)=>({title:active?'““””<b><font color=#FFFFFF>'+name+'</font></b>':'‘‘’’<font color=#777785>'+name+'</font>',url:$('#noLoading#').lazyRule((k,id)=>{if(id==='')clearMyVar(k);else putMyVar(k,String(id));clearMyVar('mdai_filter_time');clearMyVar('mdai_filter_duration');clearMyVar('mdai_filter_sort');refreshPage(false);return 'hiker://empty';},key,id),col_type:'scroll_button',extra:{backgroundColor:active?'#806C63FF':'#08777785',lineVisible:false}});
            d.push(makeChip('推荐','',!cat));
            cats.forEach(c=>d.push(makeChip(c.name,c.id,String(cat)==String(c.id))));
            d.push({col_type:'blank_block'});
        }
        if(cat){
            if(pg==1)this.filterButtons(d);
            let list=this.items(this.request(this.buildVideoPath(cat,pg,this.pageSize(),true)));
            list.forEach(x=>d.push(this.videoCard(x,'video','movie_2')));
            if(!list.length&&pg==1)d.push({title:'当前分类暂无内容',url:'hiker://empty',col_type:'text_center_1'});
            return;
        }
        if(pg>1)return;
        cats.forEach((c,ci)=>{
            let list=[]; try{list=this.items(this.request('/api/v1/videos?categoryId='+encodeURIComponent(c.id)+'&page=1&size=5'));}catch(ignore){}
            if(list.length){
                let more=$('#noLoading#').lazyRule((k,id)=>{putMyVar(k,String(id));refreshPage(false);return 'hiker://empty';},key,c.id);
                d.push(this.sectionLink(c.name,'精选 '+list.length+' 条',more));
                // 每个分区用一个主推荐打破整页同尺寸卡片，其余保持双列。
                d.push(this.heroCard(list[0],'video'));
                list.slice(1,5).forEach(x=>d.push(this.videoCard(x,'video','movie_2')));
                d.push({col_type:'blank_block'});
            }
        });
    },
    dramaHome: function(d,pg) {
