    home: function() {
        let d=this.d=[], pg=MY_PAGE||1;
        try{
            if(pg==1){
                d.push({title:'🔍  搜索视频 / 短剧 / 热门关键词',desc:'',url:$.toString(()=>{let w=String(input||'').trim();if(!w)return $('hiker://empty?page=fypage&#gameTheme#').rule(()=>{$.require('mdai').search();});putMyVar('keyword',w);$.require('mdai').saveSearchWord(w);return $('hiker://empty?page=fypage&#gameTheme#').rule(()=>{$.require('mdai').search();});}),col_type:'input',extra:{defaultValue:'',onChange:$.toString(()=>{})}});
                this.modeButton(d,'🔥 AI短剧','drama');
                this.modeButton(d,'最近更新','recent');
                this.modeButton(d,'原创精选','menu1');
                this.modeButton(d,'国产视频','menu2');
