                d.push({title:'🕘 历史',url:$('#noLoading#').lazyRule(()=>{putMyVar('mdai_mode','history');refreshPage(false);return 'hiker://empty';}),col_type:'text_3',extra:{lineVisible:false}});
                d.push({title:'⚙ 设置',url:$('#noLoading#').lazyRule(()=>{putMyVar('mdai_mode','settings');refreshPage(false);return 'hiker://empty';}),col_type:'text_3',extra:{lineVisible:false}});
                d.push({col_type:'blank_block'});
            }
            let mode=getMyVar('mdai_mode','drama');
            if(mode=='settings'){if(pg==1)this.settingsBody(d);setResult(d);return;}
            if(mode=='favorites'||mode=='history'){
                if(pg>1){setResult(d);return;}
                let isFav=mode=='favorites',key=isFav?this.favKey:this.historyKey,list=this.readList(key);
                d.push(this.sectionTitle(isFav?'我的收藏':'观看历史',list.length+' 条'));
                if(!list.length)d.push({title:isFav?'还没有收藏内容':'还没有观看记录',url:'hiker://empty',col_type:'text_center_1'});
                else{d.push({title:'清空'+(isFav?'收藏':'历史'),url:$('#noLoading#').lazyRule((k)=>{setItem(k,'[]');refreshPage(false);return 'toast://已清空';},key),col_type:'scroll_button'});list.forEach(x=>d.push(this.localCard(x)));}
                setResult(d);return;
            }
            if(mode=='drama')this.dramaHome(d,pg);
            else if(mode=='recent'){
                if(pg==1){d.push(this.sectionTitle('最近更新','按发布时间'));this.filterButtons(d);}
                let list=this.items(this.request(this.buildVideoPath('',pg,this.pageSize(),true)));
                if(pg==1 && list.length){d.push(this.heroCard(list[0],'video'));list.slice(1).forEach(x=>d.push(this.videoCard(x,'video','movie_2')));}
                else list.forEach(x=>d.push(this.videoCard(x,'video','movie_2')));
            }
            else if(mode=='menu1')this.channelHome(d,1,pg);
            else if(mode=='menu2')this.channelHome(d,2,pg);
            else if(mode=='menu3')this.channelHome(d,3,pg);
            else if(mode=='posts')this.postsHome(d,pg);
        }catch(e){d.push({title:'加载失败',desc:String(e.message||e)+'\n当前接口：'+this.host(),url:$('#noLoading#').lazyRule(()=>{refreshPage(false);return 'hiker://empty';}),col_type:'text_center_1'});}
        setResult(d);
    },
    search: function() {
        let d=this.d=[],pg=MY_PAGE||1;
