var d = [];
var HOST = getMyVar("wgcg_host", "https://videoh5.86027a.xyz");
var UA = "Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36";
var PAGE = 20;

function wgcgHdr(tok) {
  var h = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/plain, */*",
    "cid": "1",
    "timestamp": String(Math.floor(Date.now() / 1000)),
    "Accept-Language": "tw",
    "User-Agent": UA,
    "Origin": HOST,
    "Referer": HOST + "/"
  };
  if (tok) h["token"] = tok;
  return h;
}
function wgcgToken() {
  var tok = getMyVar("wgcg_token", "");
  var ts = parseInt(getMyVar("wgcg_token_ts", "0"), 10) || 0;
  if (tok && (Date.now() - ts < 6 * 3600 * 1000)) return tok;
  var mc = "", hex = "0123456789abcdef";
  for (var i = 0; i < 32; i++) mc += hex.charAt(Math.floor(Math.random() * 16));
  try {
    var reg = JSON.parse(fetch(HOST + "/api/user/dunGustRegister", {
      method: "POST", headers: wgcgHdr(""), body: JSON.stringify({ machine_code: mc })
    }) || "{}");
    tok = ((reg.data || {}).token) || "";
    if (tok) {
      putMyVar("wgcg_token", tok);
      putMyVar("wgcg_token_ts", String(Date.now()));
    }
  } catch (e) {}
  return tok || "";
}
function wgcgPost(path, obj) {
  var tok = wgcgToken();
  try {
    return JSON.parse(fetch(HOST + "/api/" + path, {
      method: "POST", headers: wgcgHdr(tok), body: JSON.stringify(obj || {})
    }) || "{}");
  } catch (e2) { return {}; }
}
function wgcgVHost() {
  var v = getMyVar("wgcg_vhost", "");
  var ts = parseInt(getMyVar("wgcg_vhost_ts", "0"), 10) || 0;
  if (v && (Date.now() - ts < 3600 * 1000)) return v;
  try {
    var j = wgcgPost("user/getVideoUrl", {});
    v = String(((j.data || {}).video_url) || "").replace(/\/$/, "");
    if (v) {
      putMyVar("wgcg_vhost", v);
      putMyVar("wgcg_vhost_ts", String(Date.now()));
    }
  } catch (e) {}
  return v || "";
}
function wgcgImg(c) {
  c = String(c || "").trim();
  if (!c) return "";
  if (c.indexOf("http") === 0) return c + (/\.(jpg|jpeg|png|webp)/i.test(c) ? "" : "#.jpg");
  var vh = wgcgVHost();
  if (!vh) return "";
  return vh + (c.charAt(0) === "/" ? c : "/" + c) + "#.jpg";
}
function wgcgDur(sec) {
  try { sec = parseInt(sec, 10) || 0; } catch (e) { return ""; }
  if (sec <= 0) return "";
  var m = Math.floor(sec / 60), s = sec % 60;
  return (m < 10 ? "0" : "") + m + ":" + (s < 10 ? "0" : "") + s;
}
function wgcgPlayRule(vid) {
  return $("hiker://empty").lazyRule((vid, HOST, UA) => {
    function hdr(tok) {
      var h = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "cid": "1",
        "timestamp": String(Math.floor(Date.now() / 1000)),
        "Accept-Language": "tw",
        "User-Agent": UA,
        "Origin": HOST,
        "Referer": HOST + "/"
      };
      if (tok) h.token = tok;
      return h;
    }
    function post(path, obj) {
      var tok = getMyVar("wgcg_token", "");
      try {
        return JSON.parse(fetch(HOST + "/api/" + path, {
          method: "POST",
          headers: hdr(tok),
          body: JSON.stringify(obj || {})
        }) || "{}");
      } catch (e) { return {}; }
    }
    function absUrl(base, path) {
      path = String(path || "").trim().replace(/\\/g, "/");
      if (!path) return "";
      if (/^https?:\/\//i.test(path)) return path;
      base = String(base || "").replace(/\/$/, "");
      if (path.charAt(0) === "/") return base + path;
      return base + "/" + path;
    }
    try {
      if (!getMyVar("wgcg_token", "")) {
        var hex = "0123456789abcdef", mc = "";
        for (var i = 0; i < 32; i++) mc += hex.charAt(Math.floor(Math.random() * 16));
        var reg = JSON.parse(fetch(HOST + "/api/user/dunGustRegister", {
          method: "POST", headers: hdr(""), body: JSON.stringify({ machine_code: mc })
        }) || "{}");
        var tk = ((reg.data || {}).token) || "";
        if (tk) { putMyVar("wgcg_token", tk); putMyVar("wgcg_token_ts", String(Date.now())); }
      }
      var det = post("video/v2/detail", { id: parseInt(vid, 10) || vid });
      var dd = det.data || {};
      var pu = String(dd.pu || dd.play_url || "").trim();
      if (!pu) return "toast://暂无播放地址";

      var vh = String((((post("user/getVideoUrl", {}).data) || {}).video_url) || getMyVar("wgcg_vhost", "")).replace(/\/$/, "");
      if (!vh) return "toast://播放域名获取失败";
      putMyVar("wgcg_vhost", vh);

      var master = absUrl(vh, pu);
      var play = master;

      // 解析主 m3u8，取最高带宽分线路（避免相对路径/广告中转）
      try {
        var m3 = fetch(master, {
          headers: {
            "User-Agent": UA,
            "Referer": HOST + "/",
            "Origin": HOST,
            "Accept": "*/*"
          }
        }) || "";
        if (m3.indexOf("#EXTM3U") >= 0) {
          var lines = m3.split(/\r?\n/);
          var bestBw = -1, bestPath = "";
          var pendingBw = 0;
          for (var li = 0; li < lines.length; li++) {
            var line = lines[li].trim();
            if (line.indexOf("#EXT-X-STREAM-INF:") === 0) {
              var bm = line.match(/BANDWIDTH=(\d+)/i);
              pendingBw = bm ? parseInt(bm[1], 10) : 0;
            } else if (line && line.charAt(0) !== "#") {
              if (pendingBw >= bestBw) {
                bestBw = pendingBw;
                bestPath = line;
              }
              pendingBw = 0;
            }
          }
          if (bestPath) {
            play = absUrl(vh, bestPath);
            // 修正偶发双斜杠
            play = play.replace(/([^:])\/\//g, "$1/");
          }
        }
      } catch (eM) {}

      // 与 TVBox 插件一致：直链 + UA/Referer（不要 JSON 多包一层，减少被清流代理改写）
      var head = {
        "User-Agent": UA,
        "Referer": HOST + "/",
