            var slice = html.substring(Math.max(0, m.index - 120), m.index);
            var cm = slice.match(/tag-counter">(\d+)</);
            if (cm) count = cm[1];
            items.push({
                title: name + (count ? ' (' + count + ')' : ''),
                url: 'hiker://empty?page=fypage&tagUrl=' + encodeURIComponent(this.abs(href)) +
