            var m = String(MY_URL || '').match(/[?&]detailUrl=([^&]+)/);
            if (m) url = decodeURIComponent(m[1]);
        } catch (e) {}
        if (!url) {
            setResult([{ title: '无效链接', col_type: 'text_center_1' }]);
            return;
        }
        var html = '';
