        try {
            var m = String(MY_URL || '').match(/[?&]kw=([^&]+)/);
            if (m) kw = decodeURIComponent(m[1]);
            else if (String(MY_URL || '').indexOf('##') >= 0) kw = String(MY_URL).split('##').pop();
        } catch (e) {}
        if (!kw) kw = getMyVar('aj_kw', '');
