js:
var B = 'https://cj.lziapi.com/api.php/provide/vod/';
var t = MY_CATE || '';
var pg = parseInt(MY_PAGE, 10) || 1;
var tries = t ? ['?ac=detail&t=' + t + '&pg=' + pg, '?ac=detail&type_id=' + t + '&pg=' + pg] : ['?ac=detail&pg=' + pg];
var list = [];
for (var k = 0; k < tries.length; k++) {
  var j = {};
  try { j = JSON.parse(fetch(B + tries[k], { headers: { 'User-Agent': MOBILE_UA } }) || '{}'); } catch (e) { j = {}; }
  list = j.list || j.data || [];
  if (list.length) break;
}
var d = [];
for (var i = 0; i < list.length; i++) {
  d.push(itemOf(list[i], B));
}
if (list.length >= 20) setNextPage(String(pg + 1));
setResult(d);
function itemOf(it, api) {
  var id = String(it.vod_id || it.id || '');
  var name = String(it.vod_name || it.name || '');
  if (!id || !name) return { title: '', url: 'hiker://empty' };
  return {
    title: name,
    img: String(it.vod_pic || it.pic || ''),
    desc: String(it.vod_remarks || it.vod_year || ''),
    col_type: 'movie_3',
    url: $('').lazyRule(function (B, vid) {
      var r = {};
      try { r = JSON.parse(fetch(B + '?ac=detail&ids=' + vid, { headers: { 'User-Agent': MOBILE_UA } }) || '{}'); } catch (e) { r = {}; }
      var one = (r.list || r.data || [])[0] || {};
      var pu = String(one.vod_play_url || '');
      var urls = [], names = [];
      var groups = pu.split('$$$');
      for (var g = 0; g < groups.length; g++) {
        var eps = groups[g].split('#'), picked = '';
        for (var e = 0; e < eps.length; e++) {
          var p = eps[e].split('$');
          var link = p[p.length - 1] || '';
          if (/^https?:\/\//.test(link)) { picked = link; names.push(p[0] || ('第' + (e + 1) + '集')); break; }
        }
        if (picked) urls.push(picked);
        if (urls.length >= 5) break;
      }
      if (!urls.length) return 'toast://这条没有播放地址';
      var dr = [], pg2 = [], dn = [], pn = [];
      for (var i = 0; i < urls.length; i++) {
        if (/\.(m3u8|mp4|flv|mkv|ts)(\?|#|$)/i.test(urls[i])) { dr.push(urls[i]); dn.push(names[i]); }
        else { pg2.push(urls[i]); pn.push(names[i]); }
      }
      return JSON.stringify({ urls: dr.concat(pg2), names: dn.concat(pn), parse: 0 });
    }, api, id)
  };
}

